cssCode:
.zoom-wrap {
  height: 200vh;
}
.zoom-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: #e6e6fa;
}
.zoom-text {
  font-size: 300px;
  font-weight: 900;
  font-family: sans-serif;
  color: #1a1a2e;
  transform: scale(5); /* શરૂઆતમાં ખૂબ મોટો અક્ષર */
  opacity: 0;
  transition: transform 0.1s linear, opacity 0.1s linear;
}
.sub-text {
  position: absolute;
  font-size: 24px;
  font-family: sans-serif;
  color: #ff007f;
  font-weight: bold;
  opacity: 0;
  transform: translateY(50px);
  transition: opacity 0.1s linear, transform 0.1s linear;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#e6e6fa;';

const wrap = document.createElement('div');
wrap.className = 'zoom-wrap';

const sticky = document.createElement('div');
sticky.className = 'zoom-sticky';

const giantText = document.createElement('div');
giantText.className = 'zoom-text';
giantText.innerText = 'M';

const subText = document.createElement('div');
subText.className = 'sub-text';
subText.innerText = 'MOTIONZYNC STUDIOS';

sticky.appendChild(giantText);
sticky.appendChild(subText);
wrap.appendChild(sticky);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const progress = c.scrollTop / maxScroll;

  // અક્ષર મોટો હોય તેમાંથી નાનો થશે
  const scale = Math.max(1, 5 - (progress * 6));
  giantText.style.transform = `scale(${scale})`;
  giantText.style.opacity = Math.min(1, progress * 3);

  // અક્ષર બરાબર ગોઠવાઈ જાય પછી બીજું લખાણ દેખાશે
  if (progress > 0.6) {
    const subProg = (progress - 0.6) * 2.5;
    subText.style.opacity = Math.min(1, subProg);
    subText.style.transform = `translateY(${Math.max(0, 50 - (subProg * 50))}px)`;
  } else {
    subText.style.opacity = 0;
    subText.style.transform = `translateY(50px)`;
  }
});
